# ORTHREGA: Orthogonal regression - fit an ellipse to data points
# Variables: H11, H12, H22, G1, G2 (5 ellipse params) + X(I), Y(I) for I=1..NPTS
# where NPTS = 4^LEVELS
# Objective: sum_I [(X(I)-XD(I))^2 + (Y(I)-YD(I))^2] (L2 groups)
# Constraints E(I): H11*X^2 + 2*H12*X*Y + H22*Y^2 - 2*G1*X - 2*G2*Y = 1
# Data generated by fractal construction
function orthrega_model(LEVELS = 6; T = Float64, backend = nothing, kwargs...)
    A_val = 9.0; B_val = 6.0; CX = 0.5; CY = 0.5
    PI = pi

    # Generate data points
    NPTS = 1
    XD_list = [CX]; YD_list = [CY]

    A = A_val; B = B_val

    for lev in 1:LEVELS
        NP = NPTS
        XZ = copy(XD_list); YZ = copy(YD_list)
        new_X = Float64[]; new_Y = Float64[]
        NPTS = 0
        for j in 1:NP
            NPTS += 1; push!(new_X, XZ[j] + A); push!(new_Y, YZ[j] + A)
            NPTS += 1; push!(new_X, XZ[j] + B); push!(new_Y, YZ[j] - B)
            NPTS += 1; push!(new_X, XZ[j] - A); push!(new_Y, YZ[j] - A)
            NPTS += 1; push!(new_X, XZ[j] - B); push!(new_Y, YZ[j] + B)
        end
        XD_list = new_X; YD_list = new_Y
        A /= PI; B /= PI
    end

    XD = T.(XD_list); YD = T.(YD_list)

    # Variables: H11(1), H12(2), H22(3), G1(4), G2(5), X(1..NPTS), Y(1..NPTS)
    nvar = 5 + 2 * NPTS
    idx_H11 = 1; idx_H12 = 2; idx_H22 = 3; idx_G1 = 4; idx_G2 = 5
    idx_X(i) = 5 + i
    idx_Y(i) = 5 + NPTS + i

    lvar = fill(T(-Inf), nvar)
    uvar = fill(T(Inf), nvar)
    start = zeros(T, nvar)
    start[idx_H11] = T(1.0); start[idx_H22] = T(1.0)
    for I in 1:NPTS
        start[idx_X(I)] = XD[I]; start[idx_Y(I)] = YD[I]
    end

    c = ExaModels.ExaCore(T; backend = backend, concrete = Val(true))
    ExaModels.@add_var(c, x, nvar; lvar = lvar, uvar = uvar, start = start)
    ExaModels.@add_par(c, θ_XD, XD[I] for I in 1:NPTS)
    ExaModels.@add_par(c, θ_YD, YD[I] for I in 1:NPTS)

    # Objective: L2 groups
    ExaModels.@add_obj(c, (x[idx_X(I)] - θ_XD[I])^2 for I in 1:NPTS)
    ExaModels.@add_obj(c, (x[idx_Y(I)] - θ_YD[I])^2 for I in 1:NPTS)

    # Constraints E(I): H11*X^2 + 2*H12*X*Y + H22*Y^2 - 2*G1*X - 2*G2*Y - 1 = 0
    ExaModels.@add_con(c,
        x[idx_H11] * x[idx_X(I)]^2 +
        T(2) * x[idx_H12] * x[idx_X(I)] * x[idx_Y(I)] +
        x[idx_H22] * x[idx_Y(I)]^2 -
        T(2) * x[idx_G1] * x[idx_X(I)] -
        T(2) * x[idx_G2] * x[idx_Y(I)] - T(1.0)
        for I in 1:NPTS)

    return ExaModels.ExaModel(c; kwargs...)
end
